def run_demo():
    """Run demo with sample data"""
    
    print("\n" + "="*80)
    print("RUNNING OPPORTUNITY SCANNER WITH SAMPLE DATA")
    print("="*80)
    
    # Create scanner
    scanner = OpportunityScanner(SAMPLE_INDEX, SAMPLE_CE, option_type="CE")
    
    # Build higher timeframes
    scanner.build_timeframes()
    
    # Find opportunities on 1-min data
    print("\n" + "-"*80)
    print("1-MINUTE TIMEFRAME ANALYSIS")
    print("-"*80)
    scanner.find_opportunities(index_threshold=10, min_profit=5, timeframe="1min")
    scanner.print_table()
    
    # Find opportunities on 5-min data
    print("\n" + "-"*80)
    print("5-MINUTE TIMEFRAME ANALYSIS")
    print("-"*80)
    scanner.find_opportunities(index_threshold=15, min_profit=5, timeframe="5min")
    scanner.print_table()


def run_with_your_data(index_data: dict, ce_data: dict):
    """
    Run with your actual Groww API data
    
    Example:
        # After fetching from Groww
        run_with_your_data(index_response, ce_response)
    """
    scanner = OpportunityScanner(index_data, ce_data, option_type="CE")
    scanner.build_timeframes()
    
    # Analyze all timeframes
    for tf in ["1min", "5min", "15min"]:
        threshold = 10 if tf == "1min" else (15 if tf == "5min" else 25)
        scanner.find_opportunities(index_threshold=threshold, min_profit=5, timeframe=tf)
        scanner.print_table()
        scanner.export_csv(f"opportunities_{tf}.csv")


if __name__ == "__main__":
    run_demo()